import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import { call, t } from '../api';
import PlaceSearch from './PlaceSearch';

/**
 * "I'm visiting Chicago Dec 3-7": a travel pin that ends by itself. Members
 * who live nearby get a notification, so they can meet up. The server saves
 * the city's centre, like a home place.
 */

const tt = (key, params = {}) => t(`trip.${key}`, params);
function iso(date) {
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}
export default class TripModal extends FormModal {
  place = null;
  starts = Stream(iso(new Date()));
  ends = Stream(iso(new Date(Date.now() + 3 * 86400000)));
  className() {
    return 'MemberMapTripModal Modal--small';
  }
  title() {
    return tt('title');
  }
  content() {
    const today = iso(new Date());
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("p", {
      className: "helpText"
    }, tt('help')), m(PlaceSearch, {
      id: "member-map-trip-place",
      label: tt('where'),
      onpick: place => this.place = place
    }), m("div", {
      className: "Form-group MemberMapDates"
    }, m("label", null, tt('from'), m("input", {
      className: "FormControl",
      type: "date",
      min: today,
      bidi: this.starts,
      required: true
    })), m("label", null, tt('to'), m("input", {
      className: "FormControl",
      type: "date",
      min: this.starts() || today,
      bidi: this.ends,
      required: true
    }))), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit",
      loading: this.loading,
      disabled: !this.place
    }, tt('save')))));
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.place) return;
    this.loading = true;
    call('POST', '/trips', {
      lat: this.place.lat,
      lng: this.place.lng,
      starts: this.starts(),
      ends: this.ends()
    }).then(() => {
      app.alerts.show({
        type: 'success'
      }, tt('saved'));
      this.attrs.onsave?.();
      this.hide();
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-member-map', 'forum/components/TripModal', TripModal);